                let bodySig = '';
                const body = options.body;
                if (body) {
                    if (typeof body === 'string') bodySig = body.slice(0, 128);
                    else if (typeof body === 'object') { try { bodySig = JSON.stringify(body).slice(0, 128); } catch {} }
