                        else if (className.includes('topic-count')) data['创建话题'] = value;
                        else if (className.includes('solved-count')) data['解决方案'] = value;
                    });

                    // 方法2：如果方法1没找到数据，尝试通过标签文本匹配
                    if (Object.keys(data).length === 0) {
