class Storage {
    constructor() {
        this._pending = new Map();
        this._timer = null;
        this._user = null;
        this._keyCache = new Map();
        this._valueCache = new Map();
        this._valueCacheTime = new Map();
    }

    _normalizeUsername(username) {
        if (typeof username !== 'string') return null;
        const cleaned = username.trim();
        if (!cleaned || cleaned.length > 60) return null;
        return /^[A-Za-z0-9_.-]+$/.test(cleaned) ? cleaned : null;
    }

    _getUserFromDom() {
        const selectors = [
            '.current-user a[href^="/u/"]',
            '.d-header-icons .current-user a[href^="/u/"]',
            '.header-dropdown-toggle.current-user[href^="/u/"]'
        ];
        for (const selector of selectors) {
            const link = document.querySelector(selector);
            if (!link) continue;
            const href = link.getAttribute('href') || '';
            const match = href.match(PATTERNS.USERNAME);
            const fromHref = this._normalizeUsername(match?.[1] || '');
            if (fromHref) return fromHref;
            const fromCard = this._normalizeUsername(link.getAttribute('data-user-card') || '');
            if (fromCard) return fromCard;
        }
        return null;
    }

    _getUserFromDiscourse() {
        const discourseUser = Utils.safeCall(() => window.Discourse?.User?.current?.(), null);
        return this._normalizeUsername(discourseUser?.username || '');
    }

    _isForumAnonymous() {
        const html = document.documentElement;
        const body = document.body;
        const isAnon = html?.classList?.contains('anon') || body?.classList?.contains('anon');
        const isLoggedIn = html?.classList?.contains('logged-in') || body?.classList?.contains('logged-in');
        return !!isAnon && !isLoggedIn;
    }

    _saveResolvedUser(username) {
        if (this._user === username) return username;
        this._user = username;
        this._keyCache.clear();  // 用户变化时清除 key 缓存
        GM_setValue(this._globalKey('currentUser'), username);
        return username;
    }

    // 获取当前用户
    getUser() {
        const liveUser = this._getUserFromDom() || this._getUserFromDiscourse();
        if (liveUser) {
            return this._saveResolvedUser(liveUser);
        }

        // 已确认匿名状态时，不再回退旧缓存，避免显示过期用户名
        if (this._isForumAnonymous()) {
            return this._saveResolvedUser(null);
        }

        const cached = this._normalizeUsername(GM_getValue(this._globalKey('currentUser'), null));
        return this._saveResolvedUser(cached);
    }

    setUser(username) {
        this._saveResolvedUser(this._normalizeUsername(username));
    }

    // 生成全局键
    _globalKey(key) {
        return `ldsp_${CURRENT_SITE.prefix}_${CONFIG.STORAGE_KEYS[key] || key}`;
    }

    // 生成用户键
    _userKey(key) {
        const cacheKey = `${key}_${this._user || ''}`;
        if (this._keyCache.has(cacheKey)) return this._keyCache.get(cacheKey);

        const base = CONFIG.STORAGE_KEYS[key] || key;
        const user = this.getUser();
        const result = user && CONFIG.USER_KEYS.has(key) 
            ? `ldsp_${CURRENT_SITE.prefix}_${base}_${user}`
            : `ldsp_${CURRENT_SITE.prefix}_${base}`;

        this._keyCache.set(cacheKey, result);
        return result;
    }

    // 获取用户数据
    get(key, defaultValue = null) {
        const storageKey = this._userKey(key);
        const now = Date.now();

        if (this._valueCache.has(storageKey)) {
            const cacheTime = this._valueCacheTime.get(storageKey);
            if ((now - cacheTime) < CONFIG.CACHE.VALUE_TTL) {
                return this._valueCache.get(storageKey);
            }
        }

        const value = GM_getValue(storageKey, defaultValue);
        this._valueCache.set(storageKey, value);
        this._valueCacheTime.set(storageKey, now);
        return value;
    }

    // 设置用户数据（带防抖）
    set(key, value) {
        const storageKey = this._userKey(key);
        this._valueCache.set(storageKey, value);
        this._valueCacheTime.set(storageKey, Date.now());
        this._pending.set(storageKey, value);
        this._scheduleWrite();
    }

    // 立即设置用户数据
    setNow(key, value) {
        const storageKey = this._userKey(key);
        this._valueCache.set(storageKey, value);
        this._valueCacheTime.set(storageKey, Date.now());
        GM_setValue(storageKey, value);
    }

    // 获取全局数据
    getGlobal(key, defaultValue = null) {
        return GM_getValue(this._globalKey(key), defaultValue);
    }

    // 设置全局数据（带防抖）
    setGlobal(key, value) {
        this._pending.set(this._globalKey(key), value);
        this._scheduleWrite();
    }

    // 立即设置全局数据
    setGlobalNow(key, value) {
        GM_setValue(this._globalKey(key), value);
    }

    // 调度写入
    _scheduleWrite() {
        if (this._timer) return;
        this._timer = setTimeout(() => {
            this.flush();
            this._timer = null;
        }, CONFIG.INTERVALS.STORAGE_DEBOUNCE);
    }

    // 刷新所有待写入数据
    flush() {
    }

    // 清除缓存和分页状态
    clearCache(type) {
        if (type) {
            // 清除特定类型的缓存
            for (const key of this._cache.keys()) {
                if (key.startsWith(type)) {
                    this._cache.delete(key);
                }
            }
            // 同时清除分页状态
            this._pageState.delete(type);
        } else {
            this._cache.clear();
            this._pageState.clear();
        }
    }

    // 获取分页状态
    getPageState(type) {
        return this._pageState.get(type) || { page: 0, allTopics: [], hasMore: true, search: '', batchSize: 20 };
    }

    // 设置分页状态
    setPageState(type, state) {
        this._pageState.set(type, state);
    }
}

// ==================== 主面板类 ====================
class Panel {
    constructor() {
        this._initManagers();
        this._initState();
        this._initUI();

